export interface AppTransactionState<TEdit = any> {
  isTransactionActive: boolean;
  currentTransactionStack: TEdit[];      // Edits within active transaction
  pastTransactionStack: TEdit[];         // Completed transactions (undo history)
  redoStack: TEdit[];                    // Transactions that were undone
}

export function createDefaultTransactionState(): AppTransactionState {
  return {
    isTransactionActive: false,
    currentTransactionStack: [],
    pastTransactionStack: [],
    redoStack: [],
  };
}
```

**Transaction Lifecycle** [PlainAppStore, lines 5870-6243](index.tsx#L5870-L6243):

```typescript
startTransaction(): void {
  if (this.isTransactionActive) {
    this.finalizeTransaction();  // Auto-finalize if nested
  }
  this.isTransactionActive = true;
}

finalizeTransaction(): void {
  if (this.isTransactionActive) {
    this.redoStack = [];
    if (this._currentTransactionStack.length > 0) {
      // MERGE multiple edits: join first.undo with last.do
      const edits = this._currentTransactionStack;
      if (edits.length === 1) {
        this.pastTransactionsStack.push(edits[0]);
      } else {
        const merged = { 
          do: edits[edits.length - 1].do, 
          undo: edits[0].undo 
        };
        this.pastTransactionsStack.push(merged);
      }
      this._currentTransactionStack = [];
    }
    this.isTransactionActive = false;
  }
}

abortTransaction(): void {
  if (this.isTransactionActive) {
    // Reverse apply all undo steps
    for (let i = this._currentTransactionStack.length - 1; i >= 0; i--) {
      const edit = this._currentTransactionStack[i];
      if (edit?.undo?.selectionDiff) {
        this.applySelectionDiff(edit.undo.selectionDiff);
      }
    }
    this._currentTransactionStack = [];
    this.isTransactionActive = false;
    this.notify();
  }
}
```

