**Execution Path** [DesignStore.executeCommand, lines 27924-27970](index.tsx#L27924-L27970):

```typescript
async executeCommand<T>(command: string, ...args: any[]): Promise<T> {
  // 1. Extract origin (e.g., "compose.sketchpad.user")
  let origin: string | undefined;
  let rest: any[];
  if (typeof args[0] === "string" && args[0].startsWith("compose.sketchpad.")) {
    origin = args[0];
    rest = args.slice(1);
  }

  // 2. Handle special transaction commands
  if (command === "compose.designApp.startTransaction") {
    this.startTransaction();
    return {} as T;
  }
  if (command === "compose.designApp.finalizeTransaction") {
    this.finalizeTransaction();
    return {} as T;
  }
  if (command === "compose.designApp.undo") {
    this.undo();
    return {} as T;
  }
  if (command === "compose.designApp.redo") {
    this.redo();
    return {} as T;
  }

  // 3. Get registered command callback
  const callback = this.commandRegistry.get(command);
  if (!callback) throw new Error(`Command "${command}" not found`);

  // 4. Build context
  const kitStore = this.kit();
  const state = this.snapshot();
  const kitState = kitStore.snapshot();
  const designStore = this.design();
  const design = designStore.snapshot();

  const context: DesignAppCommandContext = {
    designApp: state,
    kit: kitState,
    Guid: design.guid,
    design,
    fileUrls: kitStore.fileUrls,
    origin,
  };

  // 5. Execute command to get result with diffs
  const result = callback(context, ...rest);

  // 6. Apply design app diff
  if (result.diff) {
    this.change(result.diff);
  }

  // 7. RECORD EDIT - creates do/undo pair
  this.recordEdit(result);

  // 8. Apply kit diff if present
  if (result.kitDiff) {
    kitStore.change(result.kitDiff);
  }

  // 9. Sync state to machine
  if (result.diff?.selection && actor) {
    actor.send({ type: "DESIGN.SET_SELECTION", selection: this.state.selection });
  }

  return result as T;
}
```

