## **5. EDIT RECORDING & INVERSION**

**Record Edit** [PlainKitDiffAppStore, lines 6439-6455](index.tsx#L6439-L6455):

```typescript
protected recordEdit(result: TCommandResult): void {
  const res = result as any;
  if (this.isTransactionActive && (res.diff || res.kitDiff)) {
    this.redoStack = [];  // Invalidate redo on new action

    // Get current selection for inversion
    const selection = this.getSelection();

    // INVERT selection diff
    const inversedSelectionDiff = res.diff?.selection 
      ? this.inverseSelectionDiff(selection, res.diff.selection) 
      : undefined;

    // INVERT kit diff
    const kitStore = this.kit();
    const kitState = kitStore.getSnapshot().kit;
    const inversedKitDiff = res.kitDiff 
      ? inverseKitDiff(kitState, res.kitDiff)  // From @semio-tech/compose-js
      : undefined;

    // CREATE edit with do/undo steps
    const doStep = { kitDiff: res.kitDiff, selectionDiff: res.diff?.selection };
    const undoStep = { kitDiff: inversedKitDiff, selectionDiff: inversedSelectionDiff };
    const edit = { do: doStep, undo: undoStep } as TEdit;

    this._currentTransactionStack.push(edit);
  }
}
```

**Undo/Redo Implementation** [PlainKitDiffAppStore, lines 6374-6436](index.tsx#L6374-L6436):

```typescript
undo(): void {
  if (this.isTransactionActive) {
    // Within transaction: pop last edit and reverse it
    if (this._currentTransactionStack.length > 0) {
      const edit = this._currentTransactionStack.pop() as any;
      this.lastDeletedTransactionEdit = edit;
      if (edit?.undo) {
        if (edit.undo.kitDiff) {
          this.kit().apply(edit.undo.kitDiff);  // APPLY KIT CHANGES
        }
        if (edit.undo.selectionDiff) {
          this.applySelectionDiff(edit.undo.selectionDiff);  // APPLY SELECTION
        }
      }
      this.notify();
    }
  } else {
    // Outside transaction: undo finalized transaction
    if (this.pastTransactionsStack.length > 0) {
      const edit = this.pastTransactionsStack.pop() as any;
      this.redoStack.push(edit);
      if (edit?.undo) {
        if (edit.undo.kitDiff) {
          this.kit().apply(edit.undo.kitDiff);
        }
        if (edit.undo.selectionDiff) {
          this.applySelectionDiff(edit.undo.selectionDiff);
        }
      }
      this.notify();
    }
  }
}

redo(): void {
  if (this.isTransactionActive) {
    // Within transaction: redo last deleted edit
    if (this.lastDeletedTransactionEdit) {
      this._currentTransactionStack.push(this.lastDeletedTransactionEdit);
      const edit = this.lastDeletedTransactionEdit as any;
      this.lastDeletedTransactionEdit = undefined;
      if (edit?.do) {
        if (edit.do.kitDiff) {
          this.kit().apply(edit.do.kitDiff);
        }
        if (edit.do.selectionDiff) {
          this.applySelectionDiff(edit.do.selectionDiff);
        }
      }
      this.notify();
    }
  } else {
    // Outside transaction: redo next finalized transaction
    if (this.redoStack.length > 0) {
      const edit = this.redoStack.pop() as any;
      this.pastTransactionsStack.push(edit);
      if (edit?.do) {
        if (edit.do.kitDiff) {
          this.kit().apply(edit.do.kitDiff);
        }
        if (edit.do.selectionDiff) {
          this.applySelectionDiff(edit.do.selectionDiff);
        }
      }
      this.notify();
    }
  }
}
```

