## **7. EXISTING UNDO/REDO CODE**

**Yes, fully implemented!**

- **Public API**: [lines 28070-28096](index.tsx#L28070-L28096)
  ```typescript
  export function useDesignAppUndo(): ActionHookResult<[]> {
    const store = useDesignStore() as DesignStore | null;
    const getOrigin = useOrigin();
    const action = useMemo(() => {
      if (!store) return undefined;
      return () => store.execute("compose.designApp.undo", getOrigin());
    }, [store, getOrigin]);
    return [action, !!store];
  }

  export function useDesignAppRedo(): ActionHookResult<[]> {
    const store = useDesignStore() as DesignStore | null;
    const getOrigin = useOrigin();
    const action = useMemo(() => {
      if (!store) return undefined;
      return () => store.execute("compose.designApp.redo", getOrigin());
    }, [store, getOrigin]);
    return [action, !!store];
  }
  ```

- **Transaction Control**: [lines 27988-28034](index.tsx#L27988-L28034)
  ```typescript
  export interface TransactionActions {
    start: () => void;
    finalize: () => void;
    abort: () => void;
  }

  export function useDesignAppTransaction(): [TransactionActions | undefined, boolean] {
    const store = useDesignStore() as DesignStore | null;
    const getOrigin = useOrigin();
    const canTransact = !!store;
    const actions = useMemo(() => {
      if (!store) return undefined;
      return {
        start: () => store.execute("compose.designApp.startTransaction", getOrigin()),
        finalize: () => store.execute("compose.designApp.finalizeTransaction", getOrigin()),
        abort: () => store.execute("compose.designApp.abortTransaction", getOrigin()),
      };
    }, [store, getOrigin]);
    return [actions, canTransact];
  }
  ```

